      if(state.disc) links.push({label:"\u05DB\u05DC \u05E7\u05D5\u05E8\u05E1\u05D9 "+discById(state.disc).name+" \u05D1\u05DB\u05DC \u05D4\u05D0\u05E8\u05E5", href:resultUrl(state.disc,0), alt:true});
      say(state.disc ? "\u05DE\u05E6\u05D0\u05EA\u05D9! \u05D4\u05E0\u05D4 \u05D4\u05E7\u05D5\u05E8\u05E1\u05D9\u05DD \u05D1\u05DC\u05DE\u05D9\u05D3\u05D4 \u05DE\u05E8\u05D7\u05D5\u05E7, \u05D5\u05DC\u05E6\u05D9\u05D3\u05DD \u05DB\u05DC \u05D4\u05E7\u05D5\u05E8\u05E1\u05D9\u05DD \u05D1\u05EA\u05D7\u05D5\u05DD \u05E9\u05D1\u05D7\u05E8\u05EA\u05DD (\u05D7\u05DC\u05E7\u05DD \u05DE\u05EA\u05E7\u05D9\u05D9\u05DE\u05D9\u05DD \u05D2\u05DD \u05D1\u05D6\u05D5\u05DD):" 
                     : "\u05D4\u05E0\u05D4 \u05DB\u05DC \u05D4\u05E7\u05D5\u05E8\u05E1\u05D9\u05DD \u05D1\u05DC\u05DE\u05D9\u05D3\u05D4 \u05DE\u05E8\u05D7\u05D5\u05E7:", null, links);
